   359  // ------------------------------------------------------------------------------------------------
   360  // Read a Quake 1 file
   361  void MDLImporter::InternReadFile_Quake1() {
   362      ai_assert(nullptr != pScene);
   363
   364      BE_NCONST MDL::Header *pcHeader = (BE_NCONST MDL::Header *)this->mBuffer;
   365
   366  #ifdef AI_BUILD_BIG_ENDIAN
   367      FlipQuakeHeader(pcHeader);
   368  #endif
   369
   370      ValidateHeader_Quake1(pcHeader);
   371
   372      // current cursor position in the file
   373      const unsigned char *szCurrent = (const unsigned char *)(pcHeader + 1);
   374
   375      // need to read all textures
   376      for (unsigned int i = 0; i < (unsigned int)pcHeader->num_skins; ++i) {
   377          union {
   378              BE_NCONST MDL::Skin *pcSkin;
   379              BE_NCONST MDL::GroupSkin *pcGroupSkin;
   380          };
   381          if (szCurrent + sizeof(MDL::Skin) > this->mBuffer + this->iFileSize) {
   382              throw DeadlyImportError("[Quake 1 MDL] Unexpected EOF");
   383          }
   384          pcSkin = (BE_NCONST MDL::Skin *)szCurrent;
   385
   386          AI_SWAP4(pcSkin->group);
   387
   388          // Quake 1 group-skins
   389          if (1 == pcSkin->group) {
   390              AI_SWAP4(pcGroupSkin->nb);
   391
   392              // need to skip multiple images
   393              const unsigned int iNumImages = (unsigned int)pcGroupSkin->nb;
   394              szCurrent += sizeof(uint32_t) * 2;
   395
   396              if (0 != iNumImages) {
   397                  if (!i) {
   398                      // however, create only one output image (the first)
   399                      this->CreateTextureARGB8_3DGS_MDL3(szCurrent + iNumImages * sizeof(float));
   400                  }
   401                  // go to the end of the skin section / the beginning of the next skin
   402                  szCurrent += pcHeader->skinheight * pcHeader->skinwidth +
   403                               sizeof(float) * iNumImages;
   404              }
   405          } else {
   406              szCurrent += sizeof(uint32_t);
   407              unsigned int iSkip = i ? UINT_MAX : 0;
   408              CreateTexture_3DGS_MDL4(szCurrent, pcSkin->group, &iSkip);
   409              szCurrent += iSkip;
   410          }
   411      }
   412      // get a pointer to the texture coordinates
   413      BE_NCONST MDL::TexCoord *pcTexCoords = (BE_NCONST MDL::TexCoord *)szCurrent;
   414      szCurrent += sizeof(MDL::TexCoord) * pcHeader->num_verts;
   415
   416      // get a pointer to the triangles
   417      BE_NCONST MDL::Triangle *pcTriangles = (BE_NCONST MDL::Triangle *)szCurrent;
   418      szCurrent += sizeof(MDL::Triangle) * pcHeader->num_tris;
   419      VALIDATE_FILE_SIZE(szCurrent);
   420
   421      // now get a pointer to the first frame in the file
   422      BE_NCONST MDL::Frame *pcFrames = (BE_NCONST MDL::Frame *)szCurrent;
   423      MDL::SimpleFrame *pcFirstFrame;
   424
   425      if (0 == pcFrames->type) {
   426          // get address of single frame
   427          pcFirstFrame = (MDL::SimpleFrame *)&pcFrames->frame;
   428      } else {
   429          // get the first frame in the group
   430          BE_NCONST MDL::GroupFrame *pcFrames2 = (BE_NCONST MDL::GroupFrame *)pcFrames;
   431          pcFirstFrame = &(pcFrames2->frames[0]);
   432      }
   433      BE_NCONST MDL::Vertex *pcVertices = (BE_NCONST MDL::Vertex *)((pcFirstFrame->name) + sizeof(pcFirstFrame->name));
   434      VALIDATE_FILE_SIZE((const unsigned char *)(pcVertices + pcHeader->num_verts));
   435
   436  #ifdef AI_BUILD_BIG_ENDIAN
   437      for (int i = 0; i < pcHeader->num_verts; ++i) {
   438          AI_SWAP4(pcTexCoords[i].onseam);
   439          AI_SWAP4(pcTexCoords[i].s);
   440          AI_SWAP4(pcTexCoords[i].t);
   441      }
   442
   443      for (int i = 0; i < pcHeader->num_tris; ++i) {
   444          AI_SWAP4(pcTriangles[i].facesfront);
   445          AI_SWAP4(pcTriangles[i].vertex[0]);
   446          AI_SWAP4(pcTriangles[i].vertex[1]);
   447          AI_SWAP4(pcTriangles[i].vertex[2]);
   448      }
   449  #endif
   450
   451      // setup materials
   452      SetupMaterialProperties_3DGS_MDL5_Quake1();
   453
   454      // allocate enough storage to hold all vertices and triangles
   455      aiMesh *pcMesh = new aiMesh();
   456
   457      pcMesh->mPrimitiveTypes = aiPrimitiveType_TRIANGLE;
   458      pcMesh->mNumVertices = pcHeader->num_tris * 3;
   459      pcMesh->mNumFaces = pcHeader->num_tris;
   460      pcMesh->mVertices = new aiVector3D[pcMesh->mNumVertices];
   461      pcMesh->mTextureCoords[0] = new aiVector3D[pcMesh->mNumVertices];
   462      pcMesh->mFaces = new aiFace[pcMesh->mNumFaces];
   463      pcMesh->mNormals = new aiVector3D[pcMesh->mNumVertices];
   464      pcMesh->mNumUVComponents[0] = 2;
   465
   466      // there won't be more than one mesh inside the file
   467      pScene->mRootNode = new aiNode();
   468      pScene->mRootNode->mNumMeshes = 1;
   469      pScene->mRootNode->mMeshes = new unsigned int[1];
   470      pScene->mRootNode->mMeshes[0] = 0;
   471      pScene->mNumMeshes = 1;
   472      pScene->mMeshes = new aiMesh *[1];
   473      pScene->mMeshes[0] = pcMesh;
   474
   475      // now iterate through all triangles
   476      unsigned int iCurrent = 0;
   477      for (unsigned int i = 0; i < (unsigned int)pcHeader->num_tris; ++i) {
   478          pcMesh->mFaces[i].mIndices = new unsigned int[3];
   479          pcMesh->mFaces[i].mNumIndices = 3;
   480
   481          unsigned int iTemp = iCurrent;
   482          for (unsigned int c = 0; c < 3; ++c, ++iCurrent) {
   483              pcMesh->mFaces[i].mIndices[c] = iCurrent;
   484
   485              // read vertices
   486              unsigned int iIndex = pcTriangles->vertex[c];
   487              if (iIndex >= (unsigned int)pcHeader->num_verts) {
   488                  iIndex = pcHeader->num_verts - 1;
   489                  ASSIMP_LOG_WARN("Index overflow in Q1-MDL vertex list.");
   490              }
   491
   492              aiVector3D &vec = pcMesh->mVertices[iCurrent];
   493              vec.x = (float)pcVertices[iIndex].v[0] * pcHeader->scale[0];
   494              vec.x += pcHeader->translate[0];
   495
   496              vec.y = (float)pcVertices[iIndex].v[1] * pcHeader->scale[1];
   497              vec.y += pcHeader->translate[1];
   498              //vec.y *= -1.0f;
   499
   500              vec.z = (float)pcVertices[iIndex].v[2] * pcHeader->scale[2];
   501              vec.z += pcHeader->translate[2];
   502
   503              // read the normal vector from the precalculated normal table
   504              MD2::LookupNormalIndex(pcVertices[iIndex].normalIndex, pcMesh->mNormals[iCurrent]);
   505              //pcMesh->mNormals[iCurrent].y *= -1.0f;
   506
   507              // read texture coordinates
   508              float s = (float)pcTexCoords[iIndex].s;
   509              float t = (float)pcTexCoords[iIndex].t;
   510
   511              // translate texture coordinates
   512              if (0 == pcTriangles->facesfront && 0 != pcTexCoords[iIndex].onseam) {
   513                  s += pcHeader->skinwidth * 0.5f;
   514              }
   515
   516              // Scale s and t to range from 0.0 to 1.0
   517              pcMesh->mTextureCoords[0][iCurrent].x = (s + 0.5f) / pcHeader->skinwidth;
   518              pcMesh->mTextureCoords[0][iCurrent].y = 1.0f - (t + 0.5f) / pcHeader->skinheight;
   519          }
   520          pcMesh->mFaces[i].mIndices[0] = iTemp + 2;
   521          pcMesh->mFaces[i].mIndices[1] = iTemp + 1;
   522          pcMesh->mFaces[i].mIndices[2] = iTemp + 0;
   523          pcTriangles++;
   524      }
   525      return;
   526  }
