   573  // Read a MDL 3,4,5 file
   574  void MDLImporter::InternReadFile_3DGS_MDL345() {
   575      ai_assert(nullptr != pScene);
   576
   577      // the header of MDL 3/4/5 is nearly identical to the original Quake1 header
   578      BE_NCONST MDL::Header *pcHeader = (BE_NCONST MDL::Header *)this->mBuffer;
   579  #ifdef AI_BUILD_BIG_ENDIAN
   580      FlipQuakeHeader(pcHeader);
   581  #endif
   582      ValidateHeader_Quake1(pcHeader);
   583
   584      // current cursor position in the file
   585      const unsigned char *szCurrent = (const unsigned char *)(pcHeader + 1);
   586      const unsigned char *szEnd = mBuffer + iFileSize;
   587
   588      // need to read all textures
   589      for (unsigned int i = 0; i < (unsigned int)pcHeader->num_skins; ++i) {
   590          if (szCurrent >= szEnd) {
   591              throw DeadlyImportError("Texture data past end of file.");
   592          }
   593          BE_NCONST MDL::Skin *pcSkin;
   594          pcSkin = (BE_NCONST MDL::Skin *)szCurrent;
   595          AI_SWAP4(pcSkin->group);
   596          // create one output image
   597          unsigned int iSkip = i ? UINT_MAX : 0;
   598          if (5 <= iGSFileVersion) {
   599              // MDL5 format could contain MIPmaps
   600              CreateTexture_3DGS_MDL5((unsigned char *)pcSkin + sizeof(uint32_t),
   601                      pcSkin->group, &iSkip);
   602          } else {
   603              CreateTexture_3DGS_MDL4((unsigned char *)pcSkin + sizeof(uint32_t),
   604                      pcSkin->group, &iSkip);
   605          }
   606          // need to skip one image
   607          szCurrent += iSkip + sizeof(uint32_t);
   608      }
   609      // get a pointer to the texture coordinates
   610      BE_NCONST MDL::TexCoord_MDL3 *pcTexCoords = (BE_NCONST MDL::TexCoord_MDL3 *)szCurrent;
   611      szCurrent += sizeof(MDL::TexCoord_MDL3) * pcHeader->synctype;
   612
   613      // NOTE: for MDLn formats "synctype" corresponds to the number of UV coords
   614
   615      // get a pointer to the triangles
   616      BE_NCONST MDL::Triangle_MDL3 *pcTriangles = (BE_NCONST MDL::Triangle_MDL3 *)szCurrent;
   617      szCurrent += sizeof(MDL::Triangle_MDL3) * pcHeader->num_tris;
